(()=>{'use strict';const root=document.querySelector('#objectiveLabs'),Q=s=>root.querySelector(s),reduce=matchMedia('(prefers-reduced-motion: reduce)'),sequence=['A','C','T','G','G','A'],pairs={A:'T',T:'A',C:'G',G:'C'};let mode='collision',factor='temperature',high=false,t=0,raf=0,last=0,playing=false,matched=0;
const txt=(x,y,s,size=16)=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="${size}" fill="#002D72">${s}</text>`,svg=(s,label)=>`<svg viewBox="0 0 600 330" role="img" aria-label="${label}">${s}</svg>`;
const info={temperature:['Temperature','Higher temperature increases average particle kinetic energy. Particles move faster, and a larger fraction of collisions has sufficient energy to react.'],concentration:['Concentration','More reactant particles in the same volume usually gives more collisions per second. Their average speed stays the same when temperature is unchanged.'],surface:['Surface area','Breaking a solid into smaller pieces exposes more surface for collisions. The same total amount of solid is shown.'],mixing:['Mixing / stirring','Mixing brings reactants into contact and can replenish reactants near a reacting surface. It is not the same as increasing temperature.'],enzyme:['Enzyme · extension','An enzyme is a biological catalyst. It provides a pathway with a lower activation-energy barrier and is regenerated overall. It does not heat the particles.']};
root.innerHTML='<div class="sectionhead"><div><p class="eyebrow">OBJECTIVES IN MOTION</p><h2>Make the invisible visible</h2></div><span class="pill">TWO INTERACTIVE EXPLANATIONS</span></div><div class="objective-tabs"><button data-objective="collision" aria-pressed="true">Collision theory</button><button data-objective="dna" aria-pressed="false">Build a DNA strand</button></div><div id="objectiveBody"></div>';
function pause(){playing=false;cancelAnimationFrame(raf);if(Q('#particlePlay'))Q('#particlePlay').textContent=reduce.matches?'Reduced motion · use steps':'▶ Animate particles'}
function render(){pause();Q('#objectiveBody').innerHTML=`<div class="labgrid"><div class="labvisual"><div class="objective-canvas" id="objectiveCanvas"></div><div class="objective-controls" id="objectiveControls"></div><p class="small" id="objectiveLimit"></p></div><aside class="labnotes"><h3>${mode==='collision'?'What makes a reaction faster?':'Two strands. Complementary bases.'}</h3><div class="reviewbox"><b>Predict first</b><p>${mode==='collision'?'Choose a factor. Predict what changes about the particles or the energy needed for reaction.':'If one strand begins A–C–T, which bases must be opposite it?'}</p></div><p id="objectiveExplain"></p><p id="objectiveFeedback" aria-live="polite"></p><div id="objectiveOptions"></div>${WatchLearn.inline(mode==='collision'?'rates':'genetics')}<button id="objectiveQuiz" class="primary">Practise this topic →</button></aside></div>`;
Q('#objectiveQuiz').onclick=()=>{pause();window.dispatchEvent(new CustomEvent('science-exam-topic',{detail:mode==='collision'?'rates':'genetics'}))};
if(mode==='collision'){Q('#objectiveControls').innerHTML=`<label>Factor <select id="collisionFactor">${Object.entries(info).map(([id,d])=>`<option value="${id}" ${id===factor?'selected':''}>${d[0]}</option>`).join('')}</select></label><button id="collisionChange" aria-pressed="${high}">${high?'Reset to baseline':'Apply change'}</button><button id="particlePlay" ${reduce.matches?'disabled':''}>${reduce.matches?'Reduced motion · use steps':'▶ Animate particles'}</button><button id="particleStep">Step forward</button>`;Q('#collisionFactor').onchange=e=>{pause();factor=e.target.value;high=false;t=0;render()};Q('#collisionChange').onclick=()=>{high=!high;Q('#collisionChange').textContent=high?'Reset to baseline':'Apply change';Q('#collisionChange').setAttribute('aria-pressed',high);draw()};Q('#particlePlay').onclick=()=>{if(playing){pause();return}playing=true;last=performance.now();Q('#particlePlay').textContent='Ⅱ Pause';raf=requestAnimationFrame(tick)};Q('#particleStep').onclick=()=>{pause();t+=.4;draw()};}
else{Q('#objectiveOptions').innerHTML='<p>Choose the complementary base for the highlighted position.</p><div class="base-options">'+['A','T','C','G'].map(b=>`<button data-base="${b}">${b}</button>`).join('')+'</div>';Q('#objectiveControls').innerHTML='<button id="dnaReset">Build again</button>';Q('#dnaReset').onclick=()=>{matched=0;Q('#objectiveFeedback').textContent='';draw()};root.querySelectorAll('[data-base]').forEach(b=>b.onclick=()=>{if(matched===sequence.length)return;const correct=pairs[sequence[matched]]===b.dataset.base;Q('#objectiveFeedback').textContent=correct?`${sequence[matched]} pairs with ${b.dataset.base}. ${matched===5?'Strand complete!':'Build the next pair.'}`:`Try again: A pairs with T, and C pairs with G.`;if(correct)matched++;draw()})}draw();}
function tick(now){if(!playing)return;t+=Math.min(.05,(now-last)/1000);last=now;draw();raf=requestAnimationFrame(tick)}
function bounce(v,lo,hi){const w=hi-lo,u=((v-lo)%(2*w)+2*w)%(2*w);return lo+(u>w?2*w-u:u)}
function draw(){if(mode==='dna'){let c=txt(300,25,'Complementary base pairing',21)+`<path d="M65 105H535M65 240H535" stroke="#002D72" stroke-width="8" stroke-linecap="round"/>`;sequence.forEach((base,i)=>{const x=100+i*80;c+=`<circle cx="${x}" cy="105" r="8" fill="#CC8A00"/><circle cx="${x}" cy="240" r="8" fill="#CC8A00"/><rect x="${x-24}" y="125" width="48" height="36" rx="6" fill="#E8ECEF"/>`+txt(x,150,base,22);if(i<matched)c+=`<g class="dna-pair"><path d="M${x} 162V185" stroke="#CC8A00" stroke-width="3" stroke-dasharray="3 4"/><rect x="${x-24}" y="186" width="48" height="36" rx="6" fill="#FFF0C3"/>${txt(x,212,pairs[base],22)}</g>`;else c+=`<rect x="${x-24}" y="186" width="48" height="36" rx="6" fill="white" stroke="${i===matched?'#CC8A00':'#D6DFE9'}" stroke-width="${i===matched?3:1}"/>`+txt(x,212,'?',22)});c+=txt(300,288,`${matched} of 6 pairs completed`,16);Q('#objectiveCanvas').innerHTML=svg(c,'Unwound DNA with six base pairs. '+matched+' complementary bases selected.');Q('#objectiveExplain').textContent='DNA contains two complementary strands. A pairs with T, and C pairs with G. The blue rails represent sugar–phosphate backbones; dotted links represent hydrogen bonding between bases. A nucleotide contains a sugar, phosphate and base.';Q('#objectiveLimit').textContent='An unwound schematic: DNA is a double helix. Base shapes, bond counts and scale are simplified; these six pairs are not a complete gene.';root.querySelectorAll('[data-base]').forEach(b=>b.disabled=matched===6);return;}
let c=txt(300,24,info[factor][0]+(high?' · changed conditions':' · baseline'),20)+`<rect x="40" y="45" width="520" height="210" rx="16" fill="#fff" stroke="#B8C9DF"/>`;
if(factor==='enzyme'){const peak=high?120:65;c+=`<path d="M90 225Q170 225 220 ${peak}Q280 ${peak-35} 330 225T510 225" fill="none" stroke="#CC8A00" stroke-width="5"/><path d="M90 225V65" stroke="#002D72" stroke-width="2"/>`+txt(315,275,'Reaction pathway →',15)+txt(300,high?95:50,high?'Lower activation barrier':'Higher activation barrier',15);for(let i=0;i<3;i++){const x=95+((t*40+i*110)%400);c+=`<circle cx="${x}" cy="240" r="6" fill="#2E6EA6"/>`}}
else{const n=factor==='concentration'&&high?28:14,speed=factor==='temperature'&&high?1.8:1;for(let i=0;i<n;i++){const x=bounce(65+i*47+t*(i%2?42:-35)*speed,55,545),y=bounce(65+i*31+t*(i%3?26:-32)*speed+(factor==='mixing'&&high?Math.sin(t+i)*35:0),60,240);c+=`<circle cx="${x}" cy="${y}" r="7" fill="${i%2?'#CC8A00':'#2E6EA6'}"/>`;}if(factor==='surface'){if(high)for(let i=0;i<4;i++)c+=`<rect x="${210+i%2*95}" y="${85+Math.floor(i/2)*85}" width="40" height="40" fill="#002D72" rx="2"/>`;else c+='<rect x="260" y="110" width="80" height="80" fill="#002D72" rx="3"/>';}}
c+=txt(300,310,high?'Compare with your prediction':'Apply a change, then animate or step',15);Q('#objectiveCanvas').innerHTML=svg(c,'Qualitative '+info[factor][0]+' model, '+(high?'changed':'baseline')+' conditions.');Q('#objectiveExplain').textContent=info[factor][1];Q('#objectiveLimit').textContent='Qualitative illustration, not measured kinetics. Particles reflect at container walls; reaction events and product formation are not simulated. The enzyme panel is an energy diagram, not particle trajectories.';}
root.querySelectorAll('[data-objective]').forEach(b=>b.onclick=()=>{mode=b.dataset.objective;root.querySelectorAll('[data-objective]').forEach(x=>x.setAttribute('aria-pressed',x===b));render()});document.addEventListener('click',e=>{const a=e.target.closest('[data-objective-jump]');if(!a)return;e.preventDefault();mode=a.dataset.objectiveJump;root.querySelectorAll('[data-objective]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.objective===mode));render();root.scrollIntoView({behavior:reduce.matches?'auto':'smooth'})});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});reduce.addEventListener('change',()=>{pause();render()});render();window.addEventListener('science-view-changed',pause);})();
